<div class="login"><h1>تغییر رمز مدیریت</h1><?php if(!$valid):?><p class="muted">این لینک معتبر نیست، منقضی شده یا قبلاً استفاده شده است.</p><a href="/admin/forgot">درخواست لینک جدید</a><?php else:?><form method="post" action="/admin/reset"><?=csrf_field()?><input type="hidden" name="token" value="<?=e($token)?>"><input type="password" name="password" minlength="10" required placeholder="رمز جدید — حداقل ۱۰ کاراکتر"><input type="password" name="password_confirm" minlength="10" required placeholder="تکرار رمز جدید"><button class="btn" onclick="return document.querySelector('[name=password]').value===document.querySelector('[name=password_confirm]').value">تغییر رمز</button></form><?php endif;?></div>
